import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {TextDecoder} from 'node:util';

export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let first = true;
  let pending = '';
  let data = [];
  let event;
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function lineReceived(line, frames) {
    if (terminated) {
      if (line !== '') throw new Error('Nonblank line after termination');
      return;
    }
    if (line === '') {
      if (data.length) {
        const value = data.join('\n');
        if (value === '[DONE]') terminated = true;
        else frames.push({event: event || 'message', data: value});
      }
      data = [];
      event = undefined;
      return;
    }
    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') data.push(value);
    else if (field === 'event') event = value;
  }

  function receive(text, frames) {
    if (first && text.length) {
      first = false;
      if (text[0] === '\uFEFF') text = text.slice(1);
    }
    pending += text;
    let start = 0;
    let lf;
    // Each iteration advances beyond LF, independently of CR stripping.
    while ((lf = pending.indexOf('\n', start)) !== -1) {
      const end = lf > start && pending[lf - 1] === '\r' ? lf - 1 : lf;
      lineReceived(pending.slice(start, end), frames);
      start = lf + 1;
    }
    pending = pending.slice(start);
  }

  function guarded(operation) {
    try {
      if (poisoned || finished) throw new Error('Decoder is closed');
      return operation();
    } catch (error) {
      poisoned = true;
      throw error;
    }
  }

  return {
    push(chunk) {
      return guarded(() => {
        if (!(chunk instanceof Uint8Array)) throw new Error('Expected Uint8Array');
        const frames = [];
        receive(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      });
    },
    finish() {
      return guarded(() => {
        receive(utf8.decode(), []);
        if (pending !== '') throw new Error('Unterminated line');
        if (!terminated || data.length || event !== undefined) {
          throw new Error('Incomplete stream');
        }
        finished = true;
        return [];
      });
    },
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv.length !== 3) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
    const input = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(fs.readFileSync(process.argv[2])));
    if (input === null || typeof input !== 'object' || Array.isArray(input) || !Array.isArray(input.chunks)) {
      throw new Error('Expected an object with a chunks array');
    }
    const decoder = createDecoder();
    const frames = [];
    for (const encoded of input.chunks) {
      if (typeof encoded !== 'string') throw new Error('Expected base64 string');
      const chunk = Buffer.from(encoded, 'base64');
      if (chunk.toString('base64') !== encoded) throw new Error('Noncanonical base64');
      for (const frame of decoder.push(chunk)) frames.push(frame);
    }
    decoder.finish();
    process.stdout.write(JSON.stringify({frames}) + '\n');
  } catch (error) {
    process.stderr.write(String(error.message) + '\n');
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

const end = Buffer.from('data: [DONE]\n\n');
function decode(chunks) {
  const decoder = createDecoder();
  const frames = chunks.flatMap(chunk => decoder.push(chunk));
  assert.deepEqual(decoder.finish(), []);
  return frames;
}

test('whole, every two-part split, and one-byte chunks preserve UTF-8 and BOM', () => {
  const bytes = Buffer.from('\uFEFFevent: 名\r\ndata: 雪😀\r\ndata: x\ry\uFEFF\r\n\r\ndata: [DONE]\n\n\r\n');
  const original = Buffer.from(bytes);
  const expected = [{event: '名', data: '雪😀\nx\ry\uFEFF'}];
  assert.deepEqual(decode([bytes]), expected);
  for (let i = 0; i <= bytes.length; i++) {
    assert.deepEqual(decode([bytes.subarray(0, i), bytes.subarray(i)]), expected);
  }
  assert.deepEqual(decode([...bytes].map(byte => Uint8Array.of(byte))), expected);
  assert.deepEqual(bytes, original);
});

test('split CRLF dispatches only on the blank line, retaining other CRs', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: a\r')), []);
  assert.deepEqual(d.push(Buffer.from('\ndata: b\r\rc\r')), []);
  assert.deepEqual(d.push(Buffer.from('\n\r')), []);
  assert.deepEqual(d.push(Buffer.from('\n')), [{event: 'message', data: 'a\nb\r\rc'}]);
  assert.deepEqual(d.push(end), []);
  assert.deepEqual(d.finish(), []);
});

test('field parsing, resets, comments, empty data and exact DONE matching', () => {
  const source = 'event: discarded\nunknown: x\n:comment\n\n' +
    'event: old\nevent:\ndata\n\n' +
    'event: custom\ndata:  a:b \nData: ignored\n:ignored\ndata:\n\n' +
    'data: [DONE] \n\n' +
    'data: [DONE]\ndata: x\n\n' +
    'data: \uFEFF\n\n' +
    'event: ignored\ndata: [DONE]\n\n\n';
  assert.deepEqual(decode([Buffer.from(source)]), [
    {event: 'message', data: ''},
    {event: 'custom', data: ' a:b \n'},
    {event: 'message', data: '[DONE] '},
    {event: 'message', data: '[DONE]\nx'},
    {event: 'message', data: '\uFEFF'},
  ]);
});

const rejectionCases = [
  ['string chunk', d => d.push('')],
  ['null chunk', d => d.push(null)],
  ['array chunk', d => d.push([])],
  ['other typed array', d => d.push(new Uint16Array())],
  ['array buffer', d => d.push(new ArrayBuffer(0))],
  ['invalid UTF-8', d => d.push(Uint8Array.of(0xff))],
  ['overlong UTF-8', d => d.push(Uint8Array.of(0xc0, 0xaf))],
  ['surrogate UTF-8', d => d.push(Uint8Array.of(0xed, 0xa0, 0x80))],
  ['invalid continuation', d => { d.push(Uint8Array.of(0xe2)); d.push(Uint8Array.of(0x41)); }],
  ['incomplete UTF-8 at finish', d => { d.push(end); d.push(Uint8Array.of(0xf0, 0x9f)); d.finish(); }],
  ['no marker', d => d.finish()],
  ['pending data', d => { d.push(Buffer.from('data: [DONE]\n')); d.finish(); }],
  ['pending event', d => { d.push(Buffer.from('event:\n')); d.finish(); }],
  ['unterminated final line', d => { d.push(end); d.push(Buffer.from('x')); d.finish(); }],
  ['trailing CR', d => { d.push(end); d.push(Buffer.from('\r')); d.finish(); }],
  ['second marker', d => { d.push(end); d.push(end); }],
  ...[':comment', 'unknown: value', 'event:', 'data:', ' '].map(line => [
    `post-marker ${line}`, d => { d.push(end); d.push(Buffer.from(line + '\n')); },
  ]),
  ['second BOM is data', d => d.push(Buffer.from('\uFEFF\uFEFFdata: [DONE]\n\ndata: [DONE]\n\n:bad\n'))],
  ['repeated finish', d => { d.push(end); d.finish(); d.finish(); }],
  ['push after finish', d => { d.push(end); d.finish(); d.push(new Uint8Array()); }],
];
for (const [name, trigger] of rejectionCases) {
  test(`rejection poisons decoder: ${name}`, () => {
    const d = createDecoder();
    assert.throws(() => trigger(d), Error);
    assert.throws(() => d.push(end), Error);
    assert.throws(() => d.finish(), Error);
    assert.deepEqual(decode([new Uint8Array(), end]), []);
  });
}

test('a failed push does not return partial frames or change earlier returned values', () => {
  const d = createDecoder();
  const earlier = d.push(Buffer.from('data: first\n\n'));
  let returned;
  assert.throws(() => { returned = d.push(Buffer.from('data: second\n\ndata: [DONE]\n\n:bad\n')); }, Error);
  assert.equal(returned, undefined);
  assert.deepEqual(earlier, [{event: 'message', data: 'first'}]);
});

test('only one initial BOM is stripped', () => {
  assert.deepEqual(decode([Buffer.from('\uFEFF\uFEFFdata: ignored\n\ndata: [DONE]\n\n')]), []);
});

test('CLI validates arguments, files, JSON, base64 and protocol without partial stdout', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  const cli = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
  const fixture = path.join(dir, 'input.json');
  function run(args) {
    const result = spawnSync(process.execPath, [cli, ...args], {encoding: 'utf8'});
    assert.ifError(result.error);
    assert.equal(result.signal, null);
    return result;
  }
  function invalid(args) {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  }
  function write(value) { fs.writeFileSync(fixture, JSON.stringify(value)); }
  try {
    const bytes = Buffer.from('data: 雪\n\ndata: [DONE]\n\n');
    write({chunks: ['', ...[...bytes].map(b => Buffer.from([b]).toString('base64'))], extra: true});
    const result = run([fixture]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({frames: [{event: 'message', data: '雪'}]}) + '\n');
    invalid([]);
    invalid([fixture, 'extra']);
    invalid([path.join(dir, 'missing')]);
    invalid([dir]);
    for (const value of [null, [], 1, 'x', {}, {chunks: null}, {chunks: 'x'}, {chunks: []}, {chunks: [null]}]) {
      write(value); invalid([fixture]);
    }
    for (const encoded of ['Zg', 'Zg=', 'Zg===', 'Zg==\n', ' Zg==', '-w==', '_w==', 'Zh==', 'Zm9=', '====', '!!!!']) {
      write({chunks: [encoded]}); invalid([fixture]);
    }
    for (const bytes of [Buffer.from('data: ok\n\n'), Buffer.from('data: ok\n\ndata: [DONE]\n\n:bad\n'), Buffer.from([0xff])]) {
      write({chunks: [bytes.toString('base64')]}); invalid([fixture]);
    }
    fs.writeFileSync(fixture, '{broken'); invalid([fixture]);
    fs.writeFileSync(fixture, Buffer.from([0xff])); invalid([fixture]);
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `await import(${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)})`], {encoding: 'utf8'});
    assert.ifError(imported.error);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

