    {event: 'message', data: ''},
    {event: 'custom', data: ' a:b \n'},
    {event: 'message', data: '[DONE] '},
    {event: 'message', data: '[DONE]\nx'},
    {event: 'message', data: '\uFEFF'},
  ]);
});

