  ['string chunk', d => d.push('')],
  ['null chunk', d => d.push(null)],
  ['array chunk', d => d.push([])],
  ['other typed array', d => d.push(new Uint16Array())],
  ['array buffer', d => d.push(new ArrayBuffer(0))],
  ['invalid UTF-8', d => d.push(Uint8Array.of(0xff))],
  ['overlong UTF-8', d => d.push(Uint8Array.of(0xc0, 0xaf))],
  ['surrogate UTF-8', d => d.push(Uint8Array.of(0xed, 0xa0, 0x80))],
  ['invalid continuation', d => { d.push(Uint8Array.of(0xe2)); d.push(Uint8Array.of(0x41)); }],
  ['incomplete UTF-8 at finish', d => { d.push(end); d.push(Uint8Array.of(0xf0, 0x9f)); d.finish(); }],
