test('CLI validates arguments, files, JSON, base64 and protocol without partial stdout', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  const cli = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
  const fixture = path.join(dir, 'input.json');
  function run(args) {
    const result = spawnSync(process.execPath, [cli, ...args], {encoding: 'utf8'});
    assert.ifError(result.error);
    assert.equal(result.signal, null);
    return result;
  }
  function invalid(args) {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  }
  function write(value) { fs.writeFileSync(fixture, JSON.stringify(value)); }
  try {
    const bytes = Buffer.from('data: 雪\n\ndata: [DONE]\n\n');
    write({chunks: ['', ...[...bytes].map(b => Buffer.from([b]).toString('base64'))], extra: true});
    const result = run([fixture]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({frames: [{event: 'message', data: '雪'}]}) + '\n');
    invalid([]);
    invalid([fixture, 'extra']);
    invalid([path.join(dir, 'missing')]);
    invalid([dir]);
    for (const value of [null, [], 1, 'x', {}, {chunks: null}, {chunks: 'x'}, {chunks: []}, {chunks: [null]}]) {
      write(value); invalid([fixture]);
    }
    for (const encoded of ['Zg', 'Zg=', 'Zg===', 'Zg==\n', ' Zg==', '-w==', '_w==', 'Zh==', 'Zm9=', '====', '!!!!']) {
      write({chunks: [encoded]}); invalid([fixture]);
    }
    for (const bytes of [Buffer.from('data: ok\n\n'), Buffer.from('data: ok\n\ndata: [DONE]\n\n:bad\n'), Buffer.from([0xff])]) {
      write({chunks: [bytes.toString('base64')]}); invalid([fixture]);
    }
    fs.writeFileSync(fixture, '{broken'); invalid([fixture]);
    fs.writeFileSync(fixture, Buffer.from([0xff])); invalid([fixture]);
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `await import(${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)})`], {encoding: 'utf8'});
    assert.ifError(imported.error);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

